/* eslint-disable no-restricted-syntax, no-invalid-this, stdlib/no-empty-lines-between-requires */

'use strict';

// MODULES //

var EventEmitter = require( 'events' ).EventEmitter;
var logger = require( 'debug' );
var isObject = require( '@stdlib/assert/is-object' );
var setNonEnumerableReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var setNonEnumerableReadOnlyAccessor = require( '@stdlib/utils/define-nonenumerable-read-only-accessor' ); // eslint-disable-line id-length
var setReadWriteAccessor = require( '@stdlib/utils/define-read-write-accessor' );
var hasProp = require( '@stdlib/assert/has-property' );
var inherit = require( '@stdlib/utils/inherit' );
var objectKeys = require( '@stdlib/utils/keys' );
var transformErrorMessage = require( '@stdlib/plot/vega/base/transform-validation-message' );
var instance2json = require( '@stdlib/plot/vega/base/to-json' );
var format = require( '@stdlib/string/format' );
var properties = require( './properties.json' );
var defaults = require( './defaults.js' );

// Note: keep the following in alphabetical order according to the `require` path...
var getBottom = require( './bottom/get.js' );
var setBottom = require( './bottom/set.js' );

var getLeft = require( './left/get.js' );
var setLeft = require( './left/set.js' );

var getProperties = require( './properties/get.js' );

var getRight = require( './right/get.js' );
var setRight = require( './right/set.js' );

var getTop = require( './top/get.js' );
var setTop = require( './top/set.js' );


// VARIABLES //

var debug = logger( 'vega:padding:main' );


// MAIN //

/**
* Padding constructor.
*
* @constructor
* @param {Options} [options] - constructor options
* @param {number} [options.bottom=0] - bottom padding (in pixels)
* @param {number} [options.left=0] - left padding (in pixels)
* @param {number} [options.right=0] - right padding (in pixels)
* @param {number} [options.top=0] - top padding (in pixels)
* @throws {TypeError} options argument must be an object
* @throws {Error} must provide valid options
* @returns {Padding} padding instance
*
* @example
* var padding = new Padding();
* // returns <Padding>
*/
function Padding( options ) {
	var nargs;
	var opts;
	var keys;
	var v;
	var k;
	var i;

	nargs = arguments.length;
	if ( !( this instanceof Padding ) ) {
		if ( nargs ) {
			return new Padding( options );
		}
		return new Padding();
	}
	EventEmitter.call( this );

	// Resolve the default configuration:
	opts = defaults();

	// Set internal properties according to the default configuration...
	keys = objectKeys( opts );
	for ( i = 0; i < keys.length; i++ ) {
		k = keys[ i ];
		this[ '_'+k ] = opts[ k ];
	}
	if ( nargs ) {
		if ( !isObject( options ) ) {
			throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', options ) );
		}
		// Validate provided options by attempting to assign option values to corresponding fields...
		for ( i = 0; i < properties.length; i++ ) {
			k = properties[ i ];
			if ( !hasProp( options, k ) ) {
				continue;
			}
			v = options[ k ];
			try {
				this[ k ] = v;
			} catch ( err ) {
				debug( 'Encountered an error. Error: %s', err.message );

				// FIXME: retain thrown error type
				throw new Error( transformErrorMessage( err.message ) );
			}
		}
	}
	return this;
}

/*
* Inherit from the `EventEmitter` prototype.
*/
inherit( Padding, EventEmitter );

/**
* Constructor name.
*
* @private
* @name name
* @memberof Padding
* @readonly
* @type {string}
*/
setNonEnumerableReadOnly( Padding, 'name', 'Padding' );

/**
* Bottom padding (in pixels).
*
* @name bottom
* @memberof Padding.prototype
* @type {number}
* @default 0
*
* @example
* var padding = new Padding({
*     'bottom': 10
* });
*
* var v = padding.bottom;
* // returns 10
*/
setReadWriteAccessor( Padding.prototype, 'bottom', getBottom, setBottom );

/**
* Left padding (in pixels).
*
* @name left
* @memberof Padding.prototype
* @type {number}
* @default 0
*
* @example
* var padding = new Padding({
*     'left': 10
* });
*
* var v = padding.left;
* // returns 10
*/
setReadWriteAccessor( Padding.prototype, 'left', getLeft, setLeft );

/**
* Padding properties.
*
* @name properties
* @memberof Padding.prototype
* @type {Array<string>}
*
* @example
* var padding = new Padding();
*
* var v = padding.properties;
* // returns [...]
*/
setNonEnumerableReadOnlyAccessor( Padding.prototype, 'properties', getProperties );

/**
* Right padding (in pixels).
*
* @name right
* @memberof Padding.prototype
* @type {number}
* @default 0
*
* @example
* var padding = new Padding({
*     'right': 10
* });
*
* var v = padding.right;
* // returns 10
*/
setReadWriteAccessor( Padding.prototype, 'right', getRight, setRight );

/**
* Top padding (in pixels).
*
* @name top
* @memberof Padding.prototype
* @type {number}
* @default 0
*
* @example
* var padding = new Padding({
*     'top': 10
* });
*
* var v = padding.top;
* // returns 10
*/
setReadWriteAccessor( Padding.prototype, 'top', getTop, setTop );

/**
* Serializes an padding instance to a JSON object.
*
* ## Notes
*
* -   This method is implicitly invoked by `JSON.stringify`.
*
* @name toJSON
* @memberof Padding.prototype
* @type {Function}
* @returns {Object} JSON object
*
* @example
* var padding = new Padding();
*
* var v = padding.toJSON();
* // returns {...}
*/
setNonEnumerableReadOnly( Padding.prototype, 'toJSON', function toJSON() {
	return instance2json( this, properties );
});


// EXPORTS //

module.exports = Padding;
